        return responseText;
    }
    if (hasToolchainLine(text)) {
        return responseText;
    }
    var lines = null;
    try {
        lines = fetchToolchainLines(opts.workingDir);
    } catch (e) {
        lines = null;
    }
    if (!lines || lines.length === 0) {
        return responseText;
    }
