        // wrapper shell (double-quoted), NOT by dsShq.
        lines.push('touch /tmp/_registered_paths');
        lines.push('before=$(wc -l < /tmp/_registered_paths)');
        lines.push('dpath="' + opts.trailTarget + '"');
    }
    lines.push('cd "$d"');
    lines.push((env.length ? env.join(' ') + ' ' : '') +
