        // dart.sh itself (or a CI cache restore) would have put there.
        lines.push('mkdir -p "$d/nodart/dart-sdk/bin"');
        lines.push('printf %s ' + dsShq('#!/bin/sh\necho ' + dsShq(opts.managedBanner)) +
