        assert.ok(out.indexOf('toolchain: dart 3.13.5 (CI: 3.13.5, match: yes)') !== -1, 'got: ' + out);
    });

    test('a no-pin run carries the warning line too (gh-1137 AC2 at the summary level)', function () {
