 * an immediately-following toolchain-warn line when the repo has no pin.
 * Returns the array of lines, or null when no toolchain line is present.
 */
function pickToolchainLines(lines) {
    var picked = [];
    var lastPick = -1;
    for (var i = 0; i < lines.length; i++) {
